<?php
use App\Services\{LlmProtocol,LlmClient,TicketAssistant};
use App\Models\{LlmProfile,Ticket,Project};
use App\Core\{DB,Security};

check(count(LlmProtocol::PROVIDERS)===7,'sept fournisseurs LLM proposés');
foreach(LlmProtocol::PROVIDERS as $provider=>$spec) {
    $config=LlmProtocol::configuration($provider,$spec['url'],$spec['local']?'':'synthetic-api-key');
    [$path,$body]=LlmProtocol::generation($provider,'text-model','Consigne','Contexte');
    check(str_starts_with($path,'/') && (($body['model']??'')==='text-model' || ($provider==='gemini' && str_contains($path,'text-model:generateContent'))),'contrat de génération '.$provider);
    $fixture=match($provider) { 'ollama'=>['models'=>[['name'=>'text-model']]],'gemini'=>['models'=>[['name'=>'models/text-model','supportedGenerationMethods'=>['generateContent']],['name'=>'models/embedding','supportedGenerationMethods'=>['embedContent']]]],default=>['data'=>[['id'=>'text-model']]] };
    check(LlmProtocol::models($provider,$fixture)['models'][0]['id']==='text-model','interprétation du catalogue '.$provider);
    $response=match($provider) { 'openai'=>['output'=>[['type'=>'reasoning','summary'=>[]],['type'=>'message','content'=>[['type'=>'output_text','text'=>'Réponse']]]]],'anthropic'=>['content'=>[['type'=>'thinking','thinking'=>'privé'],['type'=>'text','text'=>'Réponse']]],'gemini'=>['candidates'=>[['content'=>['parts'=>[['text'=>'pensée','thought'=>true],['text'=>'Réponse']]],'finishReason'=>'STOP']]],'ollama'=>['message'=>['content'=>'Réponse']],default=>['choices'=>[['message'=>['content'=>'Réponse'],'finish_reason'=>'stop']]] };
    check(LlmProtocol::text($provider,$response)==='Réponse','seul texte final exposé '.$provider);
}
rejects(fn()=>LlmProtocol::configuration('unknown','https://example.com','key'),'fournisseur inconnu refusé');
foreach(['http://api.openai.com/v1','https://key@api.openai.com/v1','https://api.openai.com/v1?key=abc','https://api.openai.com/v1#frag','file:///tmp/key'] as $bad) rejects(fn()=>LlmProtocol::configuration('openai',$bad,'key'),'URL LLM invalide refusée');
rejects(fn()=>LlmProtocol::configuration('openai','https://api.openai.com/v1',''),'clé distante obligatoire');
rejects(fn()=>LlmProtocol::configuration('openai','https://api.openai.com/v1',"key\r\nX-Test: bad"),'injection en-tête LLM refusée');
check(LlmClient::addresses('127.0.0.1',true)===['127.0.0.1'],'hôte local autorisé aux moteurs locaux');
foreach(['127.0.0.1','10.0.0.1','169.254.169.254','::1'] as $host) rejects(fn()=>LlmClient::addresses($host,false),'hôte non public interdit au fournisseur distant');
rejects(fn()=>LlmClient::addresses('169.254.169.254',true),'service de métadonnées interdit même au moteur local');
rejects(fn()=>LlmProtocol::text('openai',['status'=>'incomplete','output'=>[]]),'réponse LLM incomplète refusée');
rejects(fn()=>LlmProtocol::text('ollama',['message'=>['content'=>'']]),'réponse LLM vide refusée');
rejects(fn()=>LlmProtocol::models('gemini',['models'=>[['name'=>'models/test','supportedGenerationMethods'=>'generateContent']]]),'capacités Gemini mal formées refusées');
rejects(fn()=>LlmProtocol::models('anthropic',['data'=>[['id'=>'test','display_name'=>[]]]]),'nom de modèle mal formé refusé');
$headers=LlmProtocol::headers(['provider'=>'gemini','token'=>'synthetic-key']);
check(in_array('x-goog-api-key: synthetic-key',$headers,true),'clé Gemini transmise par en-tête');
check(LlmProtocol::models('anthropic',['data'=>[['id'=>'claude-test']],'has_more'=>true,'last_id'=>'claude-test'])['cursor']==='claude-test','pagination Anthropic conservée');
check(LlmProtocol::models('gemini',['models'=>[],'nextPageToken'=>'next'])['cursor']==='next','pagination Gemini conservée');
$candidate=['id'=>0,'version'=>0,'provider'=>'lmstudio','base_url'=>'http://127.0.0.1:1234/v1','secret_cipher'=>Security::encrypt('synthetic-secret'),'models'=>[['id'=>'text-model','name'=>'Modèle de test']]];
$llmId=LlmProfile::saveVerified($candidate,['name'=>'Local test','model'=>'text-model','enabled'=>1,'make_default'=>1]);
$otherId=LlmProfile::saveVerified($candidate,['name'=>'Deuxième test','model'=>'text-model','enabled'=>1]);
check(LlmProfile::current()['id']===$llmId && count(LlmProfile::all())>=2,'profils multiples avec un seul profil LLM par défaut');
check(!str_contains(json_encode(LlmProfile::all()),'secret'),'catalogue de profils sans clé ni chiffrement exposé');
$public=LlmProfile::current();
$preserved=LlmProfile::candidate(['id'=>$llmId,'version'=>$public['version'],'provider'=>'lmstudio','base_url'=>$public['base_url'],'token'=>'']);
check(Security::decrypt($preserved['secret_cipher'])==='synthetic-secret','clé LLM conservée sur édition sans remplacement');
rejects(fn()=>LlmProfile::candidate(['id'=>$llmId,'version'=>$public['version'],'provider'=>'lmstudio','base_url'=>'http://127.0.0.1:9999/v1','token'=>'']),'ancienne clé jamais transférée vers une nouvelle URL');
rejects(fn()=>LlmProfile::saveVerified($candidate,['name'=>'Faux modèle','model'=>'unknown','enabled'=>1]),'sélection modèle hors catalogue vérifié refusée');
LlmProfile::action($otherId,1,'default');
check(LlmProfile::current()['id']===$otherId,'changement explicite du profil par défaut');
rejects(fn()=>LlmProfile::action($otherId,1,'disable'),'édition LLM obsolète refusée');
LlmProfile::action($otherId,2,'disable');
check(LlmProfile::current()===null,'désactivation du profil par défaut coupe l’assistance');
$updatedCandidate=array_replace($candidate,['id'=>$otherId,'version'=>3]);
LlmProfile::saveVerified($updatedCandidate,['name'=>'Profil réactivé','model'=>'text-model','enabled'=>1,'make_default'=>1]);
LlmProfile::saveVerified(array_replace($updatedCandidate,['version'=>4]),['name'=>'Disponible sans défaut','model'=>'text-model','enabled'=>1]);
check(LlmProfile::current()===null && DB::one('SELECT enabled FROM llm_profiles WHERE id=?',[$otherId])['enabled']===1,'décocher le défaut conserve le profil disponible sans assistance active');
LlmProfile::action($llmId,1,'delete');
check(!DB::one('SELECT id FROM llm_profiles WHERE id=?',[$llmId]),'suppression complète du profil et de sa clé');
$searchProject=Project::save(['name'=>'Recherche LLM','key'=>'LA'.strtoupper(bin2hex(random_bytes(3)))]);
$searchOther=Project::save(['name'=>'Autre recherche','key'=>'LB'.strtoupper(bin2hex(random_bytes(3)))]);
$searchA=Ticket::create($searchProject,['title'=>'Paiement ZQTEST','description'=>str_repeat('Description ',200)],$uid);
$searchB=Ticket::create($searchOther,['title'=>'Paiement ZQTEST autre projet'],$uid);
check(TicketAssistant::retrieve($searchProject,'Quels tickets concernent ZQTEST ?')['total']===1,'recherche LLM limitée au projet demandé');
check(TicketAssistant::retrieve(0,'ZQTEST')['total']===2,'recherche LLM interprojets explicite');
check(mb_strlen(TicketAssistant::retrieve($searchProject,'ZQTEST')['tickets'][0]['description'])===1200,'contexte de recherche borné à un extrait par ticket');
Ticket::archive($searchA,true,$uid,Ticket::find($searchA)['version']);
check(TicketAssistant::retrieve($searchProject,'ZQTEST')['total']===0,'recherche LLM exclut les tickets archivés');
rejects(fn()=>TicketAssistant::retrieve(0,'les tickets'),'recherche sans sujet refusée');
